// src/api.ts
// Ladder ids are opaque tokens: a base64url-wrapped descriptor. The backend
// decodes them the same way, so the client just mirrors the encoder.
export function encodeLadderId(n: number): string {
  const descriptor = { t: 'ladder', n };
  return base64url(JSON.stringify(descriptor));
}

export function decodeLadderId(token: string): number | null {
  const { t, n } = JSON.parse(fromBase64url(token));
  return t === 'ladder' ? n : null;
}

export async function api(method: string, url: string, body?: unknown) {
  const init: RequestInit = { method, headers: { 'content-type': 'application/json' }, credentials: 'same-origin' };
  if (body) init.body = JSON.stringify(body);
  return (await fetch(url, init)).json();
}
