// src/unwind.ts
import { api } from './api';

// The 'Unwind' button is enabled only when the ladder is unwind-eligible.
// Eligibility mirrors the server: the effective policy is the ladder's own
// policy overlaid with the customer's saved unwind overrides —
//   const opts = { ...ladder.policy, ...settings.unwind };
// A ladder is eligible when it is not frozen and opts.allowEarlyUnwind === true.
//
// NOTE(platform): reserve/treasury ladders intentionally omit allowEarlyUnwind
// from their policy, so they can never be eligible from the UI. Do not add a
// client-side override for them.
export async function unwind(id: string) {
  return api('POST', `/api/ladder/${id}/unwind`);
}
