// src/preferences.ts
import { api } from './api';

// Preferences are a nested document (display, notifications, unwind overrides).
// The client sends a partial patch; the server deep-merges it into the stored
// settings so a single leaf can be updated without resending the whole tree.
// Example partial: { display: { theme: 'dark' } }
export async function savePreferences(patch: object) {
  return api('PATCH', '/api/preferences', patch);
}
